import presentation.support.*
import kotlinx.html.*
import kotlinx.html.stream.createHTML

fun Agenda.render(): String = createHTML().body {
  h1 { +title }
  sessions.forEach { it.card() }
}

context(html: FlowContent)
fun Session.card() {
  val label = "$title · $minutes min"
